:root {
  --ink: #243349;
  --paper: #ffffff;
  --line: #d9e1ea;
  --mist: #f2f6fa;
  --blue: #3676c8;
  --green: #2f9b6a;
}

.notice {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.notice-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.lift-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  background: var(--blue);
  color: var(--paper);
  font-size: 22px;
  font-weight: 700;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 14px;
  padding: 10px 12px;
  border-radius: 9px;
  background: var(--mist);
  font-size: 14px;
  line-height: 1.35;
}

.status-row p {
  margin: 0;
}

.status-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
}

.notice-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  color: var(--ink);
  font-size: 12px;
}

button {
  padding: 7px 10px;
  border: 1px solid var(--blue);
  border-radius: 7px;
  background: var(--paper);
  color: var(--blue);
  font-size: 12px;
  font-weight: 700;
}
